import React, { useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faCalendarAlt,
  faClock,
  faMapMarkerAlt,
  faBuilding,
} from '@fortawesome/free-solid-svg-icons';
import styles from './styles.module.css';

const EventDetailCard = ({
  eventName,
  eventDate,
  eventTime,
  eventVenue,
  venueAddress,
}) => {
  return (
    <div className={styles.eventDetailContainer}>
      <h3 className={styles.eventName}>{eventName}</h3>
      <div className={styles.detailRow}>
        <FontAwesomeIcon icon={faCalendarAlt} className={styles.detailIcon} />
        <p className={styles.eventDate}>{eventDate}</p>
      </div>
      <div className={styles.detailRow}>
        <FontAwesomeIcon icon={faClock} className={styles.detailIcon} />
        <p className={styles.eventTime}>{eventTime}</p>
      </div>
      <div className={styles.detailRow}>
        <FontAwesomeIcon icon={faBuilding} className={styles.detailIcon} />
        <p className={styles.eventVenue}>{eventVenue}</p>
      </div>
      <div className={styles.detailRow}>
        <FontAwesomeIcon icon={faMapMarkerAlt} className={styles.detailIcon} />
        <p className={styles.venueAddress}>{venueAddress}</p>
      </div>
    </div>
  );
};

const EventDetails = () => {
  useEffect(() => {
    AOS.init({ duration: 1000, once: true, easing: 'ease-in-out' });
  }, []);

  const eventDetails = [
    {
      name: 'Reception',
      date: 'Thursday, 10th April 2025',
      time: '6.30 PM onwards',
      venue: 'Sengunthar Mudaliyar Samutaya Koodam',
      address: 'RMPV+7PP, Pillaiyarpalayam, Kanchipuram, Tamil Nadu 631501.',
    },
    {
      name: 'Marriage',
      date: 'Friday, 11th April 2025',
      time: '6:00 AM - 7:30 AM',
      venue: 'Sengunthar Mudaliyar Samutaya Koodam',
      address: 'RMPV+7PP, Pillaiyarpalayam, Kanchipuram, Tamil Nadu 631501.',
    },
  ];

  return (
    <div className={styles.container}>
      <div data-aos="fade-up" data-aos-delay="200" className={styles.header}>
        <p className={styles.youThere}>WE WANT YOU THERE!</p>
        <p className={styles.joinUs}>Join Our Happy Moment</p>
      </div>
      <div className={styles.eventContainer} data-aos="fade-up" data-aos-delay="400">
        {eventDetails.map((item, idx) => (
          <div key={idx} className={styles.eventCardWrapper}>
            <EventDetailCard
              eventName={item.name}
              eventDate={item.date}
              eventTime={item.time}
              eventVenue={item.venue}
              venueAddress={item.address}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default EventDetails;