import React, { useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import { HeaderSeparator, Button } from '../../components';
import styles from './styles.module.css';

const WelcomePage = () => {
  useEffect(() => {
    AOS.init({ duration: 1000, once: true, easing: 'ease-in-out' });

    const heartContainer = document.createElement('div');
    heartContainer.className = styles.heartContainer;
    document.body.appendChild(heartContainer);

    const createHeart = () => {
      const heart = document.createElement('div');
      heart.className = styles.heart;
      heart.style.left = `${Math.random() * 100}vw`;
      heart.style.animationDuration = `${3 + Math.random() * 2}s`;
      heartContainer.appendChild(heart);

      setTimeout(() => heart.remove(), 5000);
    };

    const heartInterval = setInterval(createHeart, 300);

    return () => {
      clearInterval(heartInterval);
      document.body.removeChild(heartContainer);
    };
  },);

  const handleSaveDate = () => {
    const title = encodeURIComponent('Elangovan & Indhumathi Wedding');
    const details = encodeURIComponent('Join us to celebrate the wedding of Elangovan and Indhumathi!');
    const location = encodeURIComponent('Sengunthar Mudaliyar Samutaya Koodam ( Thirumana Mandabam ),RMPV+7PP, Pillaiyarpalayam, Kanchipuram, Tamil Nadu 631501');
    const startDate = '20250410T133000Z';
    const endDate = '20250411T043000Z';

    const googleCalendarUrl = `https://www.google.com/calendar/render?action=TEMPLATE&text=${title}&details=${details}&location=${location}&dates=${startDate}/${endDate}`;
    window.open(googleCalendarUrl, '_blank');
  };

  return (
    <div className={styles.pageWrapper}>
      <div className={styles.container}>
        <div className={styles.separatorContainerCentered} data-aos="zoom-in">
          <HeaderSeparator />
          <p className={styles.textName}>ELANGOVAN &amp; INDHUMATHI </p>
          <HeaderSeparator />
        </div>

        <div className={styles.textContainer} data-aos="flip-up" data-aos-delay="200">
          <p className={styles.invitationText}>
            We are getting married, and we want you <br /> to be part of our special day
          </p>
          <p className={styles.invitationDate}>Thursday, 10th April 2025</p>
        </div>

        <div className={styles.buttonContainer} data-aos="fade-up" data-aos-delay="400">
          <Button text="Save the Date!" onClick={handleSaveDate} />
        </div>
      </div>
    </div>
  );
};

export default WelcomePage;