import React, { useState, useEffect, useRef } from 'react';
import { VolumeUp, VolumeOff } from '@material-ui/icons';
import audioSrc from '../../assets/backsound-invitation.mp3';
import styles from './styles.module.css';

const PlaySong = ({ isInvitationOpen }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef(null);

  useEffect(() => {
    audioRef.current = new Audio(audioSrc);
    audioRef.current.preload = 'auto';
    audioRef.current.load(); 
    audioRef.current.volume = 0.5;

    return () => {
      audioRef.current.pause();
      audioRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (isInvitationOpen && audioRef.current) {
      audioRef.current.play().catch((err) => console.error('Playback error:', err));
      setIsPlaying(true);
    }
  }, [isInvitationOpen]);

  const togglePlay = () => {
    if (!audioRef.current) return;

    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch((err) => console.error('Playback error:', err));
    }
    setIsPlaying((prev) => !prev);
  };

  return (
    <button className={styles.playSongButton} onClick={togglePlay}>
      {isPlaying ? <VolumeUp style={{ fontSize: 20 }} /> : <VolumeOff style={{ fontSize: 20 }} />}
    </button>
  );
};

export default PlaySong;