import React, { useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import { Button, GoogleMapLocation } from '../../components';
import styles from './styles.module.css';

const EventDetails = () => {
  useEffect(() => {
    AOS.init({ duration: 1000, once: true, easing: 'ease-in-out' });
  }, []);

  const venueName = 'Sengunthar Mudaliyar Samutaya Koodam (Thirumana Mandabam)';
  const venueNames = 'Sengunthar Mudaliyar Samutaya Koodam';
  const venueNames_sub = '(Thirumana Mandabam)';
  const venueAddress = 'RMPV+7PP, Pillaiyarpalayam, Kanchipuram, Tamil Nadu 631501.';
  const venueUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(venueName)}`;

  return (
    <div className={styles.container}>
      <div className={styles.locationSection} data-aos="fade-up" data-aos-delay="200">
        <h2 className={styles.sectionTitle}>Location</h2>
        <p className={styles.venueName}>{venueNames}</p>
        <p className={styles.venueName}>{venueNames_sub}</p>
        <p className={styles.venueAddress}>{venueAddress}</p>
      </div>

      <div className={styles.mapSection} data-aos="slide-up" data-aos-delay="400">
        <GoogleMapLocation center={venueName} zoom={14} />
        <Button text="View on Google Maps" onClick={() => window.open(venueUrl, '_blank')} />
      </div>
    </div>
  );
};

export default EventDetails;
