// Modules
import React, { useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import { ProfileCard } from '../../components';

// Assets
import styles from './styles.module.css';
import { data } from './data';

const BrideGroom = () => {
  useEffect(() => {
    AOS.init({ duration: 800, once: true, easing: 'ease-out' });
  }, []);

  return (
    <div className={styles.container}>
      <p className={styles.title} data-aos="fade-down">The Bride &amp; The Groom</p>
      <div className={styles.cardContainer}>
        {data.map((el, idx) => (
          <React.Fragment key={idx}>
            <div className={styles.profileCardWrapper} data-aos="fade-up" data-aos-delay={idx * 100}>
              <ProfileCard
                img={el.img}
                title={el.title}
                name={el.name}
                description={el.description}
                parent={el.parent}
              />
            </div>
            {(idx + 1) % 2 !== 0 && (
              <div className={styles.separator} data-aos="zoom-in" data-aos-delay={idx * 100 + 50} />
            )}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

export default BrideGroom;
