// Modules
import React, { useState, useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import styles from './styles.module.css';

const CountdownTimer = () => {
  const [days, setDays] = useState(0);
  const [hours, setHours] = useState(0);
  const [minutes, setMinutes] = useState(0);
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    AOS.init({ duration: 1000, once: true, easing: 'ease-out' });

    const interval = setInterval(() => {
      const countDownDate = new Date('April 10, 2025 08:00:00').getTime();
      const now = new Date().getTime();
      const distance = countDownDate - now;

      setDays(Math.max(0, Math.floor(distance / (1000 * 60 * 60 * 24))));
      setHours(Math.max(0, Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))));
      setMinutes(Math.max(0, Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60))));
      setSeconds(Math.max(0, Math.floor((distance % (1000 * 60)) / 1000)));

      if (distance < 0) clearInterval(interval);
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const renderCountDownValues = (data, text) => (
    <div className={styles.countdownTimeContainer} data-aos="fade-up">
      <p className={styles.countdownValue}>{data}</p>
      <p className={styles.countdownText}>{text}</p>
    </div>
  );

  return (
    <div className={styles.container}>
      <p className={styles.title} data-aos="fade-down">Countdown</p>
      <p className={styles.subtitle} data-aos="fade-down">Towards Our Wedding</p>
      <p className={styles.countdownDate} data-aos="fade-up" data-aos-delay="200">10 April 2025</p>
      <div className={styles.countdownContainer} data-aos="fade-up" data-aos-delay="400">
        {renderCountDownValues(days, 'Days')}
        <p className={styles.slash}>/</p>
        {renderCountDownValues(hours, 'Hours')}
        <p className={styles.slash}>/</p>
        {renderCountDownValues(minutes, 'Minutes')}
        <p className={styles.slash}>/</p>
        {renderCountDownValues(seconds, 'Seconds')}
      </div>
    </div>
  );
};

export default CountdownTimer;
