import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Tooltip } from 'react-leaflet';
import styles from './styles.module.css';

const KanchipuramMap = () => {
  const [coordinates, setCoordinates] = useState([12.835776573817512, 79.69436021679113]); 
  const venueName = 'Sengunthar Mudaliyar Samutaya Koodam Kanchipuram';

  useEffect(() => {
    const fetchCoordinates = async () => {
      try {
        const response = await fetch(
          `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(venueName)}`
        );
        const data = await response.json();
        if (data.length > 0) {
          setCoordinates([parseFloat(data[0].lat), parseFloat(data[0].lon)]);
        } else {
          console.warn('Location not found. Using default coordinates.');
        }
      } catch (error) {
        console.error('Error fetching location:', error);
      }
    };

    fetchCoordinates();
  }, [venueName]);

  return (
    <MapContainer
      className={styles.mapLocation}
      center={coordinates}
      zoom={15}
      scrollWheelZoom={true}
    >
      <TileLayer
        attribution='&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      <Marker position={coordinates}>
        <Tooltip direction="top" offset={[0, -10]} opacity={1} permanent>
          {venueName}
        </Tooltip>
      </Marker>
    </MapContainer>
  );
};

export default KanchipuramMap;
