import React from 'react';
import './styles.css';
import protokol1 from '../../assets/protokol-1.png';

const HealthProtocols = () => {
  return (
    <div className="health-container">
      <h2 className="fade-in">"With love in our hearts and dreams in our eyes,"</h2>
      <h2 className="zoom-in">we invite you to be a part of our joyous wedding celebration."</h2>
      <div className="protocol-container">
        <div className="names-container">
          <div className="name-box">
            <span className="name">Elangovan</span>
          </div>
          <div className="image-container">
            <img src={protokol1} alt="logo" className="circular-image" />
          </div>
          <div className="name-box">
            <span className="name">Indhumathi</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HealthProtocols;