import React, { useEffect, useState } from 'react';
import { parse } from 'qs';
import { HeaderSeparator, Button } from '../../components';
import styles from './styles.module.css'; // Or './styles.css'

const FrontPageInvitation = ({ setInvitationOpen }) => {
    const [invTo, setInvTo] = useState('');

    useEffect(() => {
        const invToParams = parse(window.location.search.substring(1));
        setInvTo(invToParams.to);
    }, []);

    return (
        <div className={styles.pageContainer}>
            <div className={styles.sprinkleContainer}>
                {Array.from({ length: 20 }).map((_, i) => (
                    <div
                        key={i}
                        className={styles.flower}
                        style={{ '--x': `${Math.random() * 100}vw`, animationDelay: `${i * 0.5}s` }}
                    />
                ))}
            </div>
            <div className={styles.container}>
                <div className={styles.separatorContainer}>
                    <HeaderSeparator />
                    <p className={styles.textName}>ELANGOVAN</p>
                    <p className={styles.textName}>&amp;</p>
                    <p className={styles.textName}>INDHUMATHI</p>
                    <HeaderSeparator />
                </div>

                <div className={styles.invitationTextContainer}> {/* Container for centering */}
                <p className={styles.invitationText}>
  {invTo && (
    <div className={styles.greetingContainer}> {/* Container for styling */}
      <span className={styles.greeting}>
        Dear&nbsp;
      </span>
      <span className={styles.invitationTo}>{invTo}</span>
    </div>
  )}
  <p className={styles.invitationText}> {/* Separate paragraph for the rest */}
    We are getting married, and we want you <br /> to be part of our special day
  </p>
</p>
                </div>

                <div className={styles.buttonContainer}>
                    <Button text="Open Invitation" onClick={() => setInvitationOpen(true)} />
                </div>
            </div>
        </div>
    );
};

export default FrontPageInvitation;